	/**
	 * Checkpoint replay re-costs recorded provider events; it is provider work, not search work. A search limit smaller
	 * than the recorded event count therefore does not prevent the replay.
	 */
	@Test
	void checkpointReplayIsChargedToProviderWorkNotSearchWork() {
		Fixture fixture = new Fixture();
		int events = fixture.checkpoint.continuationRecipe().costingTrace().eventCount();
		assertTrue(events > 1, "the checkpoint must record more than one provider event");
		ReplayRefusingProvider provider = new ReplayRefusingProvider(false);

		PackedPlanningResult result = PackedCascadesPlanner.resume(fixture.checkpoint, fixture.family,
				new PackedPlannerLimits(1L, Long.MAX_VALUE), provider);

		assertEquals(1, provider.generations.size(), "the replayed checkpoint must not be replaced");
		assertTrue(result.selectedPlan().getDoubleMetricPlanned("optimizer.planCacheRecostWorkUnits") > 0.0d,
				"a one-unit search must still replay the " + events + " recorded provider events");
		assertTrue(result.totalPrice().isPresent(), "the resumed plan must be priced");
	}

	/**
	 * A provider-work refusal during checkpoint replay rejects the checkpoint: the planner restarts on a fresh memo and
	 * runs an ordinary search, which here still prices a complete plan, instead of returning the unpriced whole-query
	 * fallback. The rejected replay is a discarded attempt, so its refusal does not make the complete fresh search
	 * incomplete.
	 */
	@Test
	void refusedCheckpointReplayRestartsAnOrdinarySearch() {
		Fixture fixture = new Fixture();
		ReplayRefusingProvider provider = new ReplayRefusingProvider(true);

		PackedPlanningResult result = PackedCascadesPlanner.resume(fixture.checkpoint, fixture.family,
				PackedPlannerLimits.unbounded(), provider);

		assertTrue(provider.refused, "the provider must refuse a replayed event");
		assertEquals(2, provider.generations.size(), "a refused replay must restart on a fresh memo generation");
		assertTrue(result.totalPrice().isPresent(),
				"a refused replay must not return the unpriced whole-query fallback: " + result.completionStatus());
		assertEquals(PackedSearchCompletionStatus.EXACT_COMPLETE, result.completionStatus(),
				"the status must describe the fresh search, not the rejected replay");
	}

	/**
	 * The cumulative checkpoint metric counts search units only. Replay re-costs provider events and is reported on the
	 * provider dimension, so its units never enter the cumulative search-unit total.
	 */
	@Test
	void cumulativeCheckpointWorkCountsSearchUnitsOnly() {
		Fixture fixture = new Fixture();
		PackedPlanningResult result = PackedCascadesPlanner.resume(fixture.checkpoint, fixture.family,
				PackedPlannerLimits.unbounded(), new ReplayRefusingProvider(false));
		double recost = result.selectedPlan().getDoubleMetricPlanned("optimizer.planCacheRecostWorkUnits");
		assertTrue(recost > 0.0d, "the checkpoint must be replayed");

		assertEquals((double) (fixture.checkpoint.cumulativeWorkUnits() + result.metrics().workUnits()),
				result.selectedPlan().getDoubleMetricPlanned("optimizer.planCacheCumulativeWorkUnits"),
				"replayed provider units were added to the cumulative search-unit metric");
	}

	/** Prices like the Frontier fixture model; optionally refuses the first replayed event once without latching. */
	private static final class ReplayRefusingProvider implements PackedCostModel {
		final List<PackedPhysicalRegion.Factory> generations = new ArrayList<>();
		private final boolean refuseFirstEvent;
		boolean refused;

		ReplayRefusingProvider(boolean refuseFirstEvent) {
			this.refuseFirstEvent = refuseFirstEvent;
		}

		@Override
		public double estimateRows(PackedQueryView query, int relationId) {
			return 1.0d;
		}

		@Override
		public PackedCostSession openSession(PackedQueryView query, PackedProviderWork work,
				PackedProviderMemory memory) {
			PackedCostSession delegate = frontierModel().openSession(query);
			return new PackedCostSession() {
				@Override
				public void bindPhysicalRegions(PackedPhysicalRegion.Factory factory) {
					generations.add(factory);
				}

				private void admit() {
					if (refuseFirstEvent && !refused) {
						refused = true;
						work.require(work.remainingWorkUnits() + 1L);
						throw new AssertionError("an oversized provider request must be refused");
					}
				}

				@Override
				public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
					admit();
					delegate.estimateLeaf(relationId, context, output);
				}

				@Override
				public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
					admit();
					delegate.appendFactor(relationId, context, output);
				}

				@Override
				public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
					admit();
					delegate.refineOperator(relationId, context, output);
				}

				@Override
				public FrontierEvidenceBundle detachEvidence(int[] evidenceStateIds) {
					return delegate.detachEvidence(evidenceStateIds);
				}

				@Override
				public void close() {
					delegate.close();
				}
			};
		}
	}

