	@Test
	void checkedProviderFailureDuringRefreshReleasesFlightAndKeepsCleanup() {
		Fixture fixture = new Fixture();
		IOException primary = new IOException("checked replay failure");
		IOException cleanup = new IOException("checked replay cleanup");
		GenerationProvider provider = new GenerationProvider(primary, cleanup);
		Throwable actual = assertThrows(Throwable.class,
				() -> PackedCascadesPlanner.refresh(fixture.refreshWork, fixture.seedCache, fixture.context, provider,
						null));
		var fingerprint = fixture.seedCache.fingerprint(fixture.source);
		var identity = PackedQueryCacheIdentity.createPlanIdentity(fixture.source);
		var next = fixture.seedCache.beginFlight(fingerprint, fixture.context, fixture.source, identity, fixture.family,
				fixture.refreshWork.limits());
		boolean nextOwnsFlight = next.owner();
		if (nextOwnsFlight) {
			fixture.seedCache.fail(next, new IllegalStateException("test releases its fresh flight"));
		}
		assertAll(() -> assertSame(primary, actual),
				() -> assertEquals(1, provider.callbacks.get()),
				() -> assertEquals(1, provider.closes.get()),
				() -> assertEquals(1, actual.getSuppressed().length),
				() -> assertTrue(actual.getSuppressed().length == 1 && actual.getSuppressed()[0] == cleanup),
				() -> assertTrue(nextOwnsFlight, "a failed refresh must not leave an owned cache flight"));
	}

	private static void assertAllCorruptions(boolean refresh) {
		List<Executable> cases = new ArrayList<>();
		for (Corruption corruption : Corruption.values()) {
			cases.add(() -> assertRejected(corruption, refresh));
		}
		assertAll(cases);
	}

	private static void assertRejected(Corruption corruption, boolean refresh) {
		Fixture fixture = new Fixture();
		PackedPlanRecipe original = fixture.checkpoint.continuationRecipe();
		PackedCostingTrace trace = corruption == Corruption.STRUCTURAL_CHILD_COUNT
				? original.costingTrace()
				: malformedTrace(original.costingTrace().eventCount(), original.frontierEvidenceBundle().stateCount(),
						corruption);
		PackedPlanContinuationSeed seed = corruption == Corruption.STRUCTURAL_CHILD_COUNT
				? oversizedStructuralSeed(original.continuationSeed())
				: original.continuationSeed();
		PackedPlanRecipe malformed = copyRecipe(original, trace, seed, fixture.entry.query());
		assertTrue(malformed.hasDetachedEvidence(), corruption.toString());
		var candidates = candidates(fixture, malformed);
		PackedSearchCheckpoint checkpoint = checkpoint(fixture, candidates);
		GenerationProvider provider = new GenerationProvider();
		PackedPlanningResult result;
		if (refresh) {
			PackedPlanCache cache = fixture.cacheWith(malformed, candidates);
			result = PackedCascadesPlanner.refresh(fixture.refreshWork, cache, fixture.context, provider, null)
					.refreshedPlan();
		} else {
			result = PackedCascadesPlanner.resume(checkpoint, fixture.family, PackedPlannerLimits.unbounded(),
					provider);
		}
		assertNotNull(result.selectedPlan(), corruption.toString());
		assertEquals(2, provider.generations.size(), corruption + " must take the typed rejection path");
		assertNotSame(provider.generations.get(0), provider.generations.get(1));
		assertTrue(provider.previousRevoked, corruption + " must revoke the old generation before rebinding");
		assertTrue(provider.replacementUsed, corruption + " must cost through the replacement generation");
		PackedPlanningResult fresh = PackedCascadesPlanner.optimize(fixture.source.clone(), OptimizationGoal.root(),
				frontierModel());
		assertEquals(fresh.selectedPlan(), result.selectedPlan(), corruption.toString());
	}

