			var fingerprint = cache.fingerprint(source);
			var identity = PackedQueryCacheIdentity.createPlanIdentity(source);
			var limits = new PackedPlannerLimits(1L, Long.MAX_VALUE);
			var decision = new PackedOptimizationDecision(family, candidates,
					PackedSearchCompletionStatus.INCOMPLETE_WORK_LIMIT, checkpoint.cumulativeWorkUnits());
